const UPCOMING_DAYS_BEFORE_DUE = 3;
const OVERDUE_STAGES = [
  { stage: 'overdue_3_days', minimumDaysOverdue: 3 },
  { stage: 'overdue_7_days', minimumDaysOverdue: 7 },
  { stage: 'overdue_14_days', minimumDaysOverdue: 14 },
];
const AMOUNT_TOLERANCE = 0.01; // Reconciliation only; never used to decide whether an amount is positive.
const configuration = $('Validate Workflow Configuration').first().json;

const raw = $json ?? {};
const fullText = value => String(value ?? '').trim().replace(/\s+/g, ' ');
const limitedText = (value, max) => fullText(value).slice(0, max);
const parseDateOnly = value => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const date = new Date(value + 'T00:00:00.000Z');
  return Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== value ? null : date;
};
const parseTimestamp = value => {
  const match = /^(\d{4}-\d{2}-\d{2})T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d{1,9})?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/.exec(value);
  if (!match || !parseDateOnly(match[1])) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
};

const invoiceIdInput = fullText(raw.invoiceId);
const invoiceId = invoiceIdInput.length <= 200 ? invoiceIdInput : '';
const customerId = limitedText(raw.customer?.id, 200);
const customerName = limitedText(raw.customer?.name, 200);
const emailInput = String(raw.customer?.email ?? '').trim().toLowerCase();
const emailParts = emailInput.split('@');
const emailLocal = emailParts[0] ?? '';
const emailDomain = emailParts[1] ?? '';
const emailValid = emailInput === '' || (
  emailInput.length <= 254 &&
  emailParts.length === 2 &&
  emailLocal.length >= 1 && emailLocal.length <= 64 &&
  !/\s/.test(emailInput) &&
  !emailLocal.startsWith('.') && !emailLocal.endsWith('.') && !emailLocal.includes('..') &&
  /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/.test(emailLocal) &&
  emailDomain.includes('.') && emailDomain.length <= 189 && !emailDomain.includes('..') &&
  emailDomain.split('.').every(label => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label))
);
const email = emailValid ? emailInput : '';
const phoneInput = String(raw.customer?.phone ?? '').trim();
const phonePrefixValid = phoneInput.startsWith('+')
  ? !phoneInput.slice(1).includes('+')
  : phoneInput.startsWith('00') && !phoneInput.includes('+');
const phoneCharactersValid = !/[a-z]/i.test(phoneInput) && /^[+\d\s()-]*$/.test(phoneInput);
const subscriberDigits = phoneInput.startsWith('+')
  ? phoneInput.slice(1).replace(/[\s()-]/g, '')
  : phoneInput.startsWith('00') ? phoneInput.slice(2).replace(/[\s()-]/g, '') : '';
const phoneValid = phoneInput === '' || (
  phonePrefixValid && phoneCharactersValid && /^[1-9]\d{3,14}$/.test(subscriberDigits)
);
const phone = phoneInput !== '' && phoneValid ? '+' + subscriberDigits : '';
const currencyInput = fullText(raw.currency).toUpperCase();
const currency = currencyInput.length <= 16 ? currencyInput : '';
const paymentStatus = limitedText(raw.paymentStatus, 40).toLowerCase().replace(/[ -]+/g, '_');
const disputed = typeof raw.disputed === 'boolean' ? raw.disputed : null;
const totalAmount = typeof raw.totalAmount === 'number' && Number.isFinite(raw.totalAmount) ? raw.totalAmount : null;
const paidAmount = typeof raw.paidAmount === 'number' && Number.isFinite(raw.paidAmount) ? raw.paidAmount : null;
const outstandingAmount = typeof raw.outstandingAmount === 'number' && Number.isFinite(raw.outstandingAmount) ? raw.outstandingAmount : null;
const dueDate = limitedText(raw.dueDate, 40);
const preparedAt = new Date().toISOString();
const errors = [];
const reviewReasons = [];

const updatedAtPresent = Object.prototype.hasOwnProperty.call(raw, 'updatedAt');
let sourceUpdatedAt = null;
if (updatedAtPresent) {
  if (typeof raw.updatedAt !== 'string' || raw.updatedAt.trim() === '') errors.push('updated_at_invalid');
  else {
    sourceUpdatedAt = parseTimestamp(raw.updatedAt.trim());
    if (!sourceUpdatedAt) errors.push('updated_at_invalid');
  }
}

const normalizedContext = {
  scope: 'invoice',
  invoiceId,
  customerId,
  customerName,
  email,
  phone,
  currency,
  totalAmount,
  paidAmount,
  outstandingAmount,
  dueDate,
  paymentStatus,
  disputed,
  sourceUpdatedAt,
  businessTimeZone: configuration.businessTimeZone,
  preparedAt,
};

if (!invoiceIdInput) errors.push('invoice_id_missing');
else if (invoiceIdInput.length > 200) errors.push('invoice_id_too_long');
if (!customerId || !customerName) errors.push('customer_identity_missing');
if (!/^[A-Z]{3}$/.test(currencyInput)) errors.push('currency_invalid');
if (totalAmount === null) errors.push('total_amount_invalid');
else if (totalAmount <= 0) errors.push('total_amount_not_positive');
if (paidAmount === null) errors.push('paid_amount_invalid');
else if (paidAmount < 0) errors.push('paid_amount_negative');
if (outstandingAmount === null) errors.push('outstanding_amount_invalid');
else if (outstandingAmount < 0) errors.push('outstanding_amount_negative');
if (disputed === null) errors.push('disputed_invalid');
const due = parseDateOnly(dueDate);
if (!due) errors.push('due_date_invalid');
if (!['unpaid', 'paid', 'partially_paid'].includes(paymentStatus)) errors.push('payment_status_invalid');

let classification = 'invalid';
let reminderStage = '';
let outputPath = 'invalid_record';
let actionReason = errors.join(',');

if (errors.length === 0) {
  const inconsistentAmount = Math.abs(totalAmount - paidAmount - outstandingAmount) > AMOUNT_TOLERANCE;
  const paidConflict = paymentStatus === 'paid' && outstandingAmount > 0;
  const unpaidConflict = paymentStatus === 'unpaid' && (paidAmount > 0 || outstandingAmount === 0);
  const partialByAmount = paidAmount > 0 && outstandingAmount > 0;

  if (inconsistentAmount) reviewReasons.push('amounts_inconsistent');
  if (paidConflict || unpaidConflict) reviewReasons.push('payment_state_conflict');
  if (emailInput && !emailValid) reviewReasons.push('customer_email_invalid');
  if (phoneInput && !phoneValid) reviewReasons.push('customer_phone_invalid');
  if (!emailInput && !phoneInput) reviewReasons.push('customer_contact_missing');

  if (disputed) {
    classification = 'disputed';
    reviewReasons.push('invoice_disputed');
  } else if (paymentStatus === 'partially_paid' || partialByAmount) {
    classification = 'partially_paid';
    reviewReasons.push('partial_payment');
  } else if (reviewReasons.length > 0) {
    classification = 'requiring_manual_review';
  } else if (paymentStatus === 'paid' && outstandingAmount === 0) {
    classification = 'paid';
    outputPath = 'no_action_required';
    actionReason = 'invoice_paid';
  } else {
    const evaluation = parseDateOnly(configuration.evaluationDate);
    const daysUntilDue = Math.round((due.getTime() - evaluation.getTime()) / 86400000);

    if (daysUntilDue > 0) {
      classification = 'upcoming';
      if (daysUntilDue <= UPCOMING_DAYS_BEFORE_DUE) reminderStage = 'upcoming_' + UPCOMING_DAYS_BEFORE_DUE + '_days';
      else actionReason = 'outside_upcoming_interval';
    } else if (daysUntilDue === 0) {
      classification = 'due';
      reminderStage = 'due_today';
    } else {
      classification = 'overdue';
      const daysOverdue = Math.abs(daysUntilDue);
      reminderStage = [...OVERDUE_STAGES].reverse().find(stage => daysOverdue >= stage.minimumDaysOverdue)?.stage ?? '';
      if (!reminderStage) actionReason = 'before_first_overdue_interval';
    }

    if (reminderStage) {
      outputPath = 'ready_for_review';
      actionReason = 'reminder_stage_eligible';
    } else outputPath = 'no_action_required';
  }

  if (reviewReasons.length > 0) {
    outputPath = 'manual_review';
    actionReason = [...new Set(reviewReasons)].join(',');
    reminderStage = '';
  }
}

const draft = reminderStage ? {
  reminderStage,
  recipient: { customerId, customerName, email, phone },
  subject: 'Payment reminder review: invoice ' + invoiceId,
  title: 'Review ' + reminderStage + ' for ' + invoiceId,
  messageVariables: { invoiceId, customerName, currency, totalAmount, paidAmount, outstandingAmount, dueDate },
  invoice: { invoiceId, currency, totalAmount, paidAmount, outstandingAmount, dueDate, paymentStatus, disputed },
  reviewStatus: 'pending_manual_approval',
} : null;

return { json: { ...normalizedContext, classification, reminderStage, outputPath, actionReason, draft } };

return $input.all().map((item, index) => {
  const value = item.json ?? {};
  if (value.outputPath !== 'ready_for_review') return item;
  const historyKey = String(value.invoiceId ?? '').trim() + '::' + String(value.reminderStage ?? '').trim();
  return { json: { ...value, historyKey }, pairedItem: { item: index } };
});

const historyByKey = new Map();

for (const item of $('Load Reminder History').all()) {
  const row = item.json ?? {};
  const invoiceId = String(row.invoice_id ?? '').trim();
  const reminderStage = String(row.reminder_stage ?? '').trim();
  if (!invoiceId || !reminderStage || row.id === undefined || row.id === null) continue;

  const key = `${invoiceId}::${reminderStage}`;
  const current = historyByKey.get(key);
  if (!current || String(row.prepared_at ?? '') > String(current.prepared_at ?? '')) historyByKey.set(key, row);
}

return $input.all().map((item, index) => {
  const invoice = item.json;
  if (invoice.outputPath !== 'ready_for_review') return item;

  const key = `${invoice.invoiceId}::${invoice.reminderStage}`;
  const history = historyByKey.get(key);
  if (!history) return item;

  return {
    json: {
      ...invoice,
      outputPath: 'already_prepared',
      actionReason: 'reminder_stage_already_prepared',
      reviewStatus: 'already_prepared',
      historyRecordId: history.id,
      previousPreparedAt: history.prepared_at ?? null,
    },
    pairedItem: { item: index },
  };
});

const groups = new Map();
for (const item of $input.all()) {
  const value = item.json ?? {};
  const historyKey = String(value.historyKey ?? '').trim();
  if (!groups.has(historyKey)) groups.set(historyKey, []);
  groups.get(historyKey).push(value);
}

const output = [];
for (const [historyKey, members] of groups) {
  const invalid = members.some(value => {
    const draft = value.draft;
    return !value.invoiceId || !value.reminderStage || !historyKey || !draft || typeof draft !== 'object' || !draft.recipient || !draft.subject || !draft.title || !draft.messageVariables || !draft.invoice || value.outputPath !== 'ready_for_review';
  });
  if (invalid) {
    for (const value of members) output.push({ json: { ...value, scope: 'invoice', outputPath: 'workflow_failure', reviewStatus: 'manual_review', failedOperation: 'output_preparation', actionReason: 'ready_output_invalid', draft: null, deliveryEnabled: false } });
    continue;
  }
  output.push({ json: { ...members[0], historyKey, batchMembers: members, outputPath: 'ready_for_review', reviewStatus: 'pending_manual_approval', deliveryEnabled: false } });
}
return output;

const preparedByKey = new Map(
  $('Prepare Ready Output').all()
    .map(item => item.json)
    .filter(value => value.outputPath === 'ready_for_review')
    .map(value => [value.historyKey, value]),
);

return $input.all().flatMap(item => {
  const row = item.json ?? {};
  const key = String(row.invoice_id ?? '').trim() + '::' + String(row.reminder_stage ?? '').trim();
  const prepared = preparedByKey.get(key);
  if (!prepared || row.id === undefined || row.id === null) {
    const members = prepared?.batchMembers ?? [{}];
    return members.map(value => ({ json: { ...value, scope: 'invoice', outputPath: 'workflow_failure', reviewStatus: 'manual_review', failedOperation: 'history_confirmation', actionReason: 'history_confirmation_failed', draft: null, deliveryEnabled: false } }));
  }
  return prepared.batchMembers.map((value, index) => ({
    json: index === 0
      ? { ...value, historyKey: key, historyRecordId: row.id, outputPath: 'ready_for_review', reviewStatus: 'pending_manual_approval', deliveryEnabled: false }
      : { ...value, historyKey: key, historyRecordId: row.id, previousPreparedAt: row.prepared_at ?? prepared.preparedAt, outputPath: 'already_prepared', actionReason: 'duplicate_in_execution', reviewStatus: 'already_prepared', deliveryEnabled: false },
  }));
});

const preparedByKey = new Map(
  $('Prepare Ready Output').all()
    .map(item => item.json)
    .filter(value => value.outputPath === 'ready_for_review')
    .map(value => [value.historyKey, value]),
);
const handled = new Set();
const output = [];
for (const item of $input.all()) {
  const value = item.json ?? {};
  const key = String(value.historyKey ?? '').trim()
    || (String(value.invoiceId ?? value.invoice_id ?? '').trim() + '::' + String(value.reminderStage ?? value.reminder_stage ?? '').trim());
  if (handled.has(key)) continue;
  handled.add(key);
  const prepared = preparedByKey.get(key);
  const members = prepared?.batchMembers ?? [value];
  for (const member of members) output.push({ json: { ...member, scope: 'invoice', outputPath: 'workflow_failure', reviewStatus: 'manual_review', failedOperation: 'history_insert', actionReason: 'history_insert_failed', draft: null, deliveryEnabled: false } });
}
return output;

const BUSINESS_TIME_ZONE = 'UTC';
const EVALUATION_DATE = '2030-06-20'; // Optional YYYY-MM-DD test override; blank uses the configured business time zone.

const parseDateOnly = value => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const date = new Date(value + 'T00:00:00.000Z');
  return Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== value ? null : date;
};
const businessDate = timeZone => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date());
  const part = type => parts.find(value => value.type === type)?.value;
  return part('year') + '-' + part('month') + '-' + part('day');
};
const failure = actionReason => [{ json: {
  scope: 'workflow',
  configurationValid: false,
  outputPath: 'workflow_failure',
  reviewStatus: 'manual_review',
  failedOperation: 'business_date_configuration',
  actionReason,
  draft: null,
  deliveryEnabled: false,
} }];

let currentBusinessDate;
try {
  currentBusinessDate = businessDate(BUSINESS_TIME_ZONE);
} catch {
  return failure('business_time_zone_invalid');
}

const configuredDate = String(EVALUATION_DATE ?? '').trim();
if (configuredDate && !parseDateOnly(configuredDate)) return failure('evaluation_date_invalid');

return [{ json: {
  scope: 'workflow',
  configurationValid: true,
  businessTimeZone: BUSINESS_TIME_ZONE,
  evaluationDate: configuredDate || currentBusinessDate,
} }];

